Trigger.TriggerText:
BEGIN
   -- Open with every customer listed.
   sales_ui.run_search;
END;

BEGIN
   MESSAGE('Customer Orders Inquiry is read-only; there is nothing to save.');
END;

BEGIN
   :CONTROL.SEARCH_NAME := NULL;
   :CONTROL.SEARCH_REGION := NULL;
   :CONTROL.MIN_CREDIT := NULL;
   sales_ui.run_search;
END;

BEGIN
   IF NOT sales_ui.g_busy THEN
      sales_ui.show_customer;
   END IF;
END;

BEGIN
   SELECT NVL(SUM(quantity * unit_price), 0)
     INTO :ORDERS.ORDER_TOTAL
     FROM ofw_order_lines
    WHERE order_id = :ORDERS.ORDER_ID;
END;

BEGIN
   IF NOT sales_ui.g_busy THEN
      sales_ui.show_lines;
   END IF;
END;

BEGIN
   -- Classic Forms lookup: show the product name for the foreign key.
   BEGIN
      SELECT product_name
        INTO :ORDER_LINES.PRODUCT_NAME
        FROM ofw_products
       WHERE product_id = :ORDER_LINES.PRODUCT_ID;
   EXCEPTION
      WHEN NO_DATA_FOUND THEN
         :ORDER_LINES.PRODUCT_NAME := '(unknown product)';
   END;
   :ORDER_LINES.LINE_TOTAL := :ORDER_LINES.QUANTITY * :ORDER_LINES.UNIT_PRICE;
END;

ProgramUnit.ProgramUnitText:
PACKAGE sales_ui IS
   -- Re-entrancy guard: coordination navigates between blocks.
   g_busy BOOLEAN := FALSE;

   PROCEDURE run_search;
   PROCEDURE show_customer;
   PROCEDURE show_lines;
   FUNCTION credit_standing (p_limit IN NUMBER, p_spent IN NUMBER) RETURN VARCHAR2;
END;

PACKAGE BODY sales_ui IS

   FUNCTION credit_standing (p_limit IN NUMBER, p_spent IN NUMBER) RETURN VARCHAR2 IS
      v_pct NUMBER;
   BEGIN
      IF NVL(p_limit, 0) = 0 THEN
         RETURN 'No credit line';
      END IF;
      v_pct := NVL(p_spent, 0) / p_limit * 100;
      IF v_pct >= 100 THEN
         RETURN 'Over limit';
      ELSIF v_pct >= 75 THEN
         RETURN 'Near limit';
      ELSE
         RETURN 'Good standing';
      END IF;
   END;

   PROCEDURE clear_summary IS
   BEGIN
      :CONTROL.SUM_ORDERS := NULL;
      :CONTROL.SUM_OPEN := NULL;
      :CONTROL.SUM_SPENT := NULL;
      :CONTROL.SUM_AVG := NULL;
      :CONTROL.SUM_LAST_ORDER := NULL;
      :CONTROL.SUM_CREDIT_USED := NULL;
      :CONTROL.SUM_STANDING := NULL;
   END;

   -- Account summary for the current customer: one aggregate query, then
   -- formatting and a credit classification done in PL/SQL.
   PROCEDURE refresh_summary IS
      v_orders NUMBER;
      v_open   NUMBER;
      v_spent  NUMBER;
      v_last   DATE;
   BEGIN
      IF :CUSTOMERS.CUSTOMER_ID IS NULL THEN
         clear_summary;
         RETURN;
      END IF;

      -- Forms' client-side PL/SQL predates ANSI joins: classic Oracle outer-join syntax.
      SELECT COUNT(*),
             SUM(DECODE(o.status, 'NEW', 1, 'SHIPPED', 1, 0)),
             NVL(SUM(t.order_total), 0),
             MAX(o.order_date)
        INTO v_orders, v_open, v_spent, v_last
        FROM ofw_orders o,
             (SELECT order_id, SUM(quantity * unit_price) order_total
                FROM ofw_order_lines
               GROUP BY order_id) t
       WHERE o.customer_id = :CUSTOMERS.CUSTOMER_ID
         AND o.status <> 'CANCELLED'
         AND t.order_id (+) = o.order_id;

      :CONTROL.SUM_ORDERS := TO_CHAR(v_orders);
      :CONTROL.SUM_OPEN := TO_CHAR(v_open);
      :CONTROL.SUM_SPENT := TO_CHAR(v_spent, 'FM$999,999,990.00');
      IF v_orders > 0 THEN
         :CONTROL.SUM_AVG := TO_CHAR(ROUND(v_spent / v_orders, 2), 'FM$999,999,990.00');
      ELSE
         :CONTROL.SUM_AVG := 'n/a';
      END IF;
      :CONTROL.SUM_LAST_ORDER := NVL(TO_CHAR(v_last, 'YYYY-MM-DD'), 'never');
      :CONTROL.SUM_CREDIT_USED := ROUND(v_spent / :CUSTOMERS.CREDIT_LIMIT * 100) || '% of '
                                  || TO_CHAR(:CUSTOMERS.CREDIT_LIMIT, 'FM$999,999,990');
      :CONTROL.SUM_STANDING := credit_standing(:CUSTOMERS.CREDIT_LIMIT, v_spent);
   END;

   -- Query the order lines of the current order (detail of ORDERS).
   PROCEDURE show_lines IS
   BEGIN
      g_busy := TRUE;
      GO_BLOCK('ORDER_LINES');
      EXECUTE_QUERY;
      GO_BLOCK('ORDERS');
      g_busy := FALSE;
   EXCEPTION
      WHEN OTHERS THEN
         g_busy := FALSE;
         RAISE;
   END;

   -- Master-detail coordination for the current customer:
   -- account summary, orders, and the lines of the first order.
   PROCEDURE show_customer IS
   BEGIN
      g_busy := TRUE;
      IF :CUSTOMERS.CUSTOMER_ID IS NULL THEN
         :CONTROL.RESULT_INFO := 'No customer selected.';
      ELSE
         :CONTROL.RESULT_INFO := 'Customer ' || :SYSTEM.CURSOR_RECORD || ': '
                                 || :CUSTOMERS.CUSTOMER_NAME || ' (' || :CUSTOMERS.CITY || ')';
      END IF;
      refresh_summary;
      GO_BLOCK('ORDERS');
      EXECUTE_QUERY;
      GO_BLOCK('ORDER_LINES');
      EXECUTE_QUERY;
      GO_BLOCK('CUSTOMERS');
      g_busy := FALSE;
   EXCEPTION
      WHEN OTHERS THEN
         g_busy := FALSE;
         RAISE;
   END;

   -- Builds the customer WHERE clause from the search fields. Every value is
   -- referenced as a bind variable (:CONTROL.x), never concatenated into SQL.
   PROCEDURE run_search IS
      v_where  VARCHAR2(500);
      v_button NUMBER;
   BEGIN
      IF :CONTROL.SEARCH_NAME IS NOT NULL THEN
         v_where := 'UPPER(customer_name) LIKE ''%'' || UPPER(:CONTROL.SEARCH_NAME) || ''%''';
      END IF;
      IF :CONTROL.SEARCH_REGION IS NOT NULL THEN
         IF v_where IS NOT NULL THEN
            v_where := v_where || ' AND ';
         END IF;
         v_where := v_where || 'region = UPPER(:CONTROL.SEARCH_REGION)';
      END IF;
      IF :CONTROL.MIN_CREDIT IS NOT NULL THEN
         IF v_where IS NOT NULL THEN
            v_where := v_where || ' AND ';
         END IF;
         v_where := v_where || 'credit_limit >= :CONTROL.MIN_CREDIT';
      END IF;

      SET_BLOCK_PROPERTY('CUSTOMERS', DEFAULT_WHERE, v_where);
      GO_BLOCK('CUSTOMERS');
      EXECUTE_QUERY;

      IF :CUSTOMERS.CUSTOMER_ID IS NULL THEN
         GO_BLOCK('ORDER_LINES');
         CLEAR_BLOCK(NO_VALIDATE);
         GO_BLOCK('ORDERS');
         CLEAR_BLOCK(NO_VALIDATE);
         clear_summary;
         :CONTROL.RESULT_INFO := 'No customers match the search.';
         v_button := SHOW_ALERT('NO_MATCH');
         IF v_button = ALERT_BUTTON1 THEN
            :CONTROL.SEARCH_NAME := NULL;
            :CONTROL.SEARCH_REGION := NULL;
            :CONTROL.MIN_CREDIT := NULL;
            run_search;
         ELSE
            GO_ITEM('CONTROL.SEARCH_NAME');
         END IF;
      END IF;
   END;

END;
